// render.mjs — the answer screen. Markdown → ANSI, line-state machine.
//
// This is a faithful port of _lil_render / _lil_scratchpad_box from the
// original lil.zsh: same palette, same glyphs, same wrap points. The files in
// tests/golden/ were generated by the zsh implementation and this module must
// reproduce them byte for byte (tests/render.test.mjs).
//
// Deliberate differences, each covered by its own test:
//   * bold / italic spans that straddle a wrap point stay styled
//   * `code` inside **bold** loses its literal backticks
//   * headers drop inline markers instead of shouting them
//   * blank lines inside a code fence survive
//   * it can render incrementally, one source line at a time (Renderer.push)

import { PAL, width, fit, charWidth } from "./ui/ansi.mjs";
import {
  OPEN_FENCE, OPEN_TAG, CLOSE_FENCE, CLOSE_TAG, ONE_LINE_TAG,
} from "./lilcmd.mjs";

const clampCols = (cols) => {
  let c = Number(cols) > 0 ? Number(cols) : 80;
  if (c < 24) c = 24;
  return c;
};

// Word-wrap at word boundaries; inline `code` spans are atomic.
export function wrapProse(text, w) {
  let prot = "";
  let inCode = false;
  for (const ch of text) {
    if (ch === "`") { inCode = !inCode; prot += ch; }
    else if (inCode && /\s/.test(ch)) prot += "\x1e";
    else prot += ch;
  }
  const out = [];
  let line = "";
  let lineW = 0;
  for (const word of prot.split(/[ \t\n]+/)) {
    if (!word) continue;
    const wordW = width(word.replaceAll("\x1e", " "));
    if (!line) { line = word; lineW = wordW; }
    else if (lineW + 1 + wordW <= w) { line += " " + word; lineW += 1 + wordW; }
    else { out.push(line); line = word; lineW = wordW; }
  }
  if (line) out.push(line);
  return out.map((l) => l.replaceAll("\x1e", " "));
}

// Character-exact wrap — display only, bytes preserved.
export function wrapHard(text, w) {
  const out = [];
  for (const src of text.split("\n")) {
    let rem = src;
    while (rem) {
      const chunk = fit(rem, w) || String.fromCodePoint(rem.codePointAt(0));
      out.push(chunk);
      rem = rem.slice(chunk.length);
    }
  }
  return out;
}

// `code` inside a bold/italic span: amber, markers dropped.
function nested(content, open) {
  if (!content.includes("`")) return open + content + PAL.RESET;
  let out = "";
  let rest = content;
  while (rest) {
    const a = rest.indexOf("`");
    const b = a < 0 ? -1 : rest.indexOf("`", a + 1);
    if (b < 0) { out += open + rest + PAL.RESET; break; }
    if (a > 0) out += open + rest.slice(0, a) + PAL.RESET;
    out += PAL.BOLD + PAL.AMBER + rest.slice(a + 1, b) + PAL.RESET;
    rest = rest.slice(b + 1);
  }
  return out;
}

// A styled span may contain "\n" (it straddled a wrap): restyle each piece.
const span = (content, open) =>
  content.split("\n").map((piece) => (piece ? nested(piece, open) : "")).join("\n");

// Inline markdown for the wrapped lines of ONE block. Same scan order as the
// zsh _lil_inline (code, then **, then *), with one extension: a ** or *
// opener with no closer on its own line may close on a later line.
export function inline(lines) {
  let rest = lines.join("\n");
  let out = "";
  while (rest) {
    if (rest[0] === "`") {
      const inner = rest.slice(1);
      const nl = inner.indexOf("\n");
      const close = inner.indexOf("`");
      if (close >= 0 && (nl < 0 || close < nl)) {
        out += PAL.AMBER + inner.slice(0, close) + PAL.RESET;
        rest = inner.slice(close + 1);
      } else { out += "`"; rest = inner; }
    } else if (rest.startsWith("**")) {
      const tail = rest.slice(2);
      const close = tail.indexOf("**");
      if (close >= 0) {
        out += span(tail.slice(0, close), PAL.BOLD + PAL.GREEN);
        rest = tail.slice(close + 2);
      } else { out += "**"; rest = tail; }
    } else if (rest[0] === "*") {
      const tail = rest.slice(1);
      const nl = tail.indexOf("\n");
      let close = tail.indexOf("*");
      const sameLine = close >= 0 && (nl < 0 || close < nl);
      // Cross-line italics only when it is unmistakably emphasis: opener hugs
      // a word, closer hugs a word. Keeps a lone `*` glob literal.
      if (!sameLine) {
        close = /^[\p{L}\p{N}]/u.test(tail) ? tail.search(/[\p{L}\p{N}.,!?)]\*(?![*\p{L}\p{N}])/u) : -1;
        if (close >= 0) close += 1;
      }
      if (close >= 0) {
        out += span(tail.slice(0, close), PAL.ITALIC + PAL.DIM);
        rest = tail.slice(close + 1);
      } else { out += "*"; rest = tail; }
    } else {
      const next = rest.search(/[`*]/);
      const head = next < 0 ? rest : rest.slice(0, next);
      out += head;
      rest = rest.slice(head.length);
    }
  }
  return out.split("\n");
}

export class Renderer {
  constructor(cols, { paraGap = false } = {}) {
    const c = clampCols(cols);
    this.W = c > 100 ? 100 : c;
    this.CW = Math.max(this.W - 4, 20);
    this.paraGap = paraGap;
    this.inFence = false;
    this.prevBlank = false;
    this.count = 0;
    this.last = "";
  }

  // Feed one source line; returns the output lines it produced.
  push(ln) {
    const out = [];
    const emit = (s) => { out.push(s); this.count++; this.last = s; };
    const gap = () => { if (this.count > 0 && this.last !== "") emit(""); };
    const nospace = ln.replace(/^\s+/, "");
    const { CW } = this;

    if (this.inFence) {
      if (nospace.startsWith("```")) {
        this.inFence = false;
        gap();
        this.prevBlank = true;
        return out;
      }
      const gutter = `${PAL.GRAY}  ┃ ${PAL.RESET}`;
      if (ln === "") emit(gutter);
      for (const chunk of wrapHard(ln, CW)) emit(`${gutter}${PAL.GREEN}${chunk}${PAL.RESET}`);
      this.prevBlank = false;
      return out;
    }
    // zsh's "${(f)text}" silently dropped empty source lines, which is why
    // paragraphs sit flush against each other. That density is the look.
    if (ln === "" && !this.paraGap) return out;
    if (nospace.startsWith("```")) {
      gap();
      this.inFence = true;
      this.prevBlank = true;
      return out;
    }
    if (ln.trim() === "") {
      if (!this.prevBlank) emit("");
      this.prevBlank = true;
      return out;
    }
    this.prevBlank = false;

    let m;
    if (/^#{1,3}\s+/.test(nospace)) {
      const htext = nospace.replace(/^#+\s+/, "").replace(/`|\*\*/g, "");
      const plain = `◆ ${htext.toUpperCase()}`;
      const rule = "─".repeat(Math.max(0, CW - width(plain)));
      emit(`${PAL.BOLD}${PAL.GREEN}  ${plain}${PAL.RESET}${PAL.AMBER}${rule}${PAL.RESET}`);
      emit("");
      this.prevBlank = true;
    } else if (/^[-*]\s+/.test(nospace)) {
      const content = nospace.slice(1).replace(/^\s+/, "");
      inline(wrapProse(content, CW)).forEach((wl, i) => {
        emit(i === 0 ? `${PAL.GREEN} ▸ ${PAL.RESET}${wl}` : `   ${wl}`);
      });
    } else if ((m = nospace.match(/^([0-9]+)[.]\s+(.*)$/))) {
      const pad = " ".repeat(m[1].length + 2);
      inline(wrapProse(m[2], CW)).forEach((wl, i) => {
        emit(i === 0 ? `${PAL.GREEN}${m[1]}.${PAL.RESET} ${wl}` : `${pad}${wl}`);
      });
    } else {
      for (const wl of inline(wrapProse(nospace, CW))) emit(`  ${wl}`);
    }
    return out;
  }
}

export function render(text, cols, opts) {
  const r = new Renderer(cols, opts);
  const out = [];
  for (const ln of text.split("\n")) out.push(...r.push(ln));
  return out.join("\n");
}

// ---------------------------------------------------------------------------
// Incremental answer: text deltas in → rendered lines out, with the trailing
// command block held back for the scratchpad instead of being printed.
// ---------------------------------------------------------------------------
export class AnswerStream {
  constructor(cols, opts) {
    this.renderer = new Renderer(cols, opts);
    this.raw = "";
    this.partial = "";
    this.held = [];        // source lines of a (maybe) command block
    this.heldOpen = null;  // closer regex while inside an unterminated block
    this.blanks = [];      // blank lines waiting to learn what follows them
  }

  // A new text block began (e.g. the turn after a tool call).
  breakLine() {
    if (this.partial) return this.write("\n");
    return [];
  }

  write(delta) {
    this.raw += delta;
    const parts = (this.partial + delta).split("\n");
    this.partial = parts.pop();
    const out = [];
    for (const ln of parts) out.push(...this.#line(ln.replace(/\r$/, "")));
    return out;
  }

  #flushHeld() {
    const out = [];
    for (const ln of [...this.blanks, ...this.held]) out.push(...this.renderer.push(ln));
    if (this.renderer.inFence) out.push(...this.renderer.push("```"));
    this.blanks = [];
    this.held = [];
    this.heldOpen = null;
    return out;
  }

  #line(ln) {
    if (this.heldOpen) {
      this.held.push(ln);
      if (this.heldOpen.test(ln)) this.heldOpen = null;
      return [];
    }
    const opener = OPEN_FENCE.test(ln) ? CLOSE_FENCE : OPEN_TAG.test(ln) ? CLOSE_TAG : null;
    const oneLine = !this.renderer.inFence && ONE_LINE_TAG.test(ln);
    if (!this.renderer.inFence && (opener || oneLine)) {
      // A second block: the first one was not the command after all.
      const out = this.held.length ? this.#flushHeld() : [];
      this.held = [ln];
      this.heldOpen = opener;
      return out;
    }
    if (ln.trim() === "" && !this.renderer.inFence) {
      if (this.held.length === 0) this.blanks.push(ln);
      return [];
    }
    // Ordinary content. A closed block stays hidden (it is still the last
    // block, so it is still the command); blank lines before it are released.
    const out = [];
    for (const b of this.blanks) out.push(...this.renderer.push(b));
    this.blanks = [];
    out.push(...this.renderer.push(ln));
    return out;
  }

  end() {
    const out = [];
    if (this.partial) {
      const ln = this.partial;
      this.partial = "";
      out.push(...this.#line(ln));
    }
    if (this.heldOpen) out.push(...this.#flushHeld()); // never closed → not a command
    return out;
  }
}

// ---------------------------------------------------------------------------
// Scratchpad box (display only — execution always uses the command verbatim)
// ---------------------------------------------------------------------------
export function boxWidth(cols) {
  let w = clampCols(cols);
  if (w > 100) w = 100;
  return w;
}

export function scratchpadBox(cmd, cols, { stamp = "AWAITING ORDERS", tone = "amber", reveal = 1 } = {}) {
  const w = boxWidth(cols);
  const edge = tone === "red" ? PAL.RED : tone === "green" ? PAL.GREEN : tone === "gray" ? PAL.GRAY : PAL.AMBER;
  const topFill = Math.max(0, w - 29);
  // "AWAITING ORDERS" is the reference stamp: 15 cells, fill = w - 24.
  const botFill = Math.max(0, w - 9 - width(stamp));
  const lines = [];
  lines.push(`${edge}  ╔═ ☢  S C R A T C H P A D ${"═".repeat(topFill)}╗${PAL.RESET}`);
  wrapHard(cmd, w - 8).forEach((line, i) => {
    const sp = " ".repeat(Math.max(0, w - 8 - width(line)));
    lines.push(i === 0
      ? `${edge}  ║ ${PAL.RESET}${PAL.BOLD}${PAL.GREEN}❯ ${line}${sp}${edge} ║${PAL.RESET}`
      : `${edge}  ║${PAL.RESET}${PAL.BOLD}${PAL.GREEN}   ${line}${sp}${edge} ║${PAL.RESET}`);
  });
  lines.push(`${edge}  ╚${"═".repeat(botFill)} ${stamp} ═══╝${PAL.RESET}`);
  if (reveal < 1) {
    const n = Math.round(w * reveal);
    return lines.map((l) => {
      let seen = 0;
      let out = "";
      for (const part of l.split(/(\x1b\[[0-9;]*m)/)) {
        if (part.startsWith("\x1b")) { out += part; continue; }
        for (const ch of part) { if (seen < n) out += ch; seen += charWidth(ch); }
      }
      return out + PAL.RESET;
    });
  }
  return lines;
}

const hint = (keys, label, strong) =>
  `${PAL.GRAY}[${PAL.RESET}${PAL.AMBER}${keys}${PAL.RESET} ` +
  `${strong ? PAL.BOLD + PAL.GREEN : PAL.DIM}${label}${PAL.RESET}${PAL.GRAY}]${PAL.RESET}`;

// The key legend under the box. `mac` keeps the ⌘ chords the WezTerm snippet
// provides; elsewhere only the keys that always work are advertised.
export function hintRow({ hasCmd, mac = false, edit = false } = {}) {
  const parts = [hint("⏎", "dismiss")];
  if (hasCmd) {
    parts.push(hint(mac ? "^R ⌘⏎" : "^R", "RUN", true));
    parts.push(hint(mac ? "^Y ⌘C" : "^Y", "copy"));
    if (edit) parts.push(hint("^E", "edit"));
  }
  parts.push(hint("✏", "type to reply"));
  return `    ${parts.join("  ")}`;
}
